DO $$DECLARE b jsonb; BEGIN
 b:=public.pilot_sales_dashboard_v3('2026-09-01','own',NULL,1,20);
 PERFORM public.test_assert(b->'summary'->'poOrderCount'->>'value'='1','PO unique order count');
 PERFORM public.test_assert(b->'summary'->'poOrderValue'->>'value'='100.00','PO order date and current eligible status');
 PERFORM public.test_assert(b->'summary'->'poDeliveryValue'->>'value'='50.00','PO delivered by nonvoid SJ date');
 PERFORM public.test_assert(b->'summary'->'coShippedCount'->>'value'='1','CO two lines one order count');
 PERFORM public.test_assert(b->'summary'->'coSaleValue'->>'value'='10.00' AND b->'summary'->'coSaleValue'->>'quality'='complete','current allocation generation only; PO-only customers have no reporting duty');
 PERFORM public.test_assert(b->'items'->0->'metrics'->'coSaleValue'->>'quality'='complete','alphabetical PO-only store has recorded zero CO without invented reporting duty');
 PERFORM public.test_assert(b->'summary'->'coShippedCount'->>'value'<>b->'summary'->'coSaleValue'->>'value','shipment count never sold value');
 PERFORM public.test_assert(b->'activity'->>'scheduled'='0' AND b->'activity'->>'visited'='0','zero-denominator activity stays counts');
END$$;
